from pathlib import Path
p = Path('src/core/lombok/javac/handlers/HandleBuilder.java')
s = p.read_text()
old = '''					JCMethodDecl md = generateDefaultProvider(bfd.nameOfDefaultProvider, fieldNode, td.typarams);
					recursiveSetGeneratedBy(md, annotationNode);'''
new = '''					JCMethodDecl md = generateDefaultProvider(bfd.nameOfDefaultProvider, fieldNode, td.typarams, annotationNode);'''
