s = s.replace('import com.sun.tools.javac.tree.JCTree.JCPrimitiveTypeTree;\n', 'import com.sun.tools.javac.tree.JCTree.JCPrimitiveTypeTree;\nimport com.sun.tools.javac.tree.JCTree.JCReturn;\n')
old = '''	public static JCMethodDecl generateDefaultProvider(Name methodName, JavacNode fieldNode, List<JCTypeParameter> params) {
		JavacTreeMaker maker = fieldNode.getTreeMaker();
		JCVariableDecl field = (JCVariableDecl) fieldNode.get();

		JCStatement statement = maker.Return(field.init);
		field.init = null;

		JCBlock body = maker.Block(0, List.<JCStatement>of(statement));
		int modifiers = Flags.PRIVATE | Flags.STATIC;
		return maker.MethodDef(maker.Modifiers(modifiers), methodName, cloneType(maker, field.vartype, fieldNode), copyTypeParams(fieldNode, params), List.<JCVariableDecl>nil(), List.<JCExpression>nil(), body, null);
	}'''
new = '''	public static JCMethodDecl generateDefaultProvider(Name methodName, JavacNode fieldNode, List<JCTypeParameter> params, JavacNode source) {
		JavacTreeMaker maker = fieldNode.getTreeMaker();
		JCVariableDecl field = (JCVariableDecl) fieldNode.get();

		JCExpression init = field.init;
		field.init = null;

		JCReturn statement = maker.Return(null);
		JCBlock body = maker.Block(0, List.<JCStatement>of(statement));
		int modifiers = Flags.PRIVATE | Flags.STATIC;
		JCMethodDecl defaultProvider = maker.MethodDef(maker.Modifiers(modifiers), methodName, cloneType(maker, field.vartype, fieldNode), copyTypeParams(fieldNode, params), List.<JCVariableDecl>nil(), List.<JCExpression>nil(), body, null);
		// Preserve the initializer's positions; javac caches argument types by source position.
		recursiveSetGeneratedBy(defaultProvider, source);
		statement.expr = init;
		return defaultProvider;
	}'''
assert s.count(old) == 1
s = s.replace(old, new)
p.write_text(s)
p = Path('src/core/lombok/javac/handlers/HandleSuperBuilder.java')
s = p.read_text()
old = '''				JCMethodDecl md = HandleBuilder.generateDefaultProvider(bfd.nameOfDefaultProvider, fieldNode, td.typarams);
				recursiveSetGeneratedBy(md, annotationNode);'''
new = '''				JCMethodDecl md = HandleBuilder.generateDefaultProvider(bfd.nameOfDefaultProvider, fieldNode, td.typarams, annotationNode);'''
assert s.count(old) == 1
p.write_text(s.replace(old, new))
p = Path('doc/changelog.markdown')
s = p.read_text()
old = '### v1.18.24 "Edgy Guinea Pig"\n'
new = old + '* BUGFIX: `@Builder.Default` initializers involving generic method arguments no longer cause incorrect type errors with javac 11 and later. Also applies to `@SuperBuilder`.\n'
assert s.count(old) == 1
p.write_text(s.replace(old, new))
